[
  {
    "subject": "The Drowned Rat",
    "fact": "The tavern has a banked hearth, three candle stubs on Marla Fenwick’s counter, and a full mug kept waiting at the miners’ table.",
    "tags": "location,establishment,atmosphere"
  },
  {
    "subject": "Marla Fenwick",
    "fact": "Marla has three fingers on her hand and watches the room with a hard, suspicious stare.",
    "tags": "npc,appearance,behavior"
  },
  {
    "subject": "Father Oswin's letter",
    "fact": "The letter in Sera Valen’s pocket says to come home at once and mentions that the mine has fallen in, Derva Saltbeard is missing, and Tam saw pale folk in the dark.",
    "tags": "item,message,plot"
  },
  {
    "subject": "Tam",
    "fact": "Tam’s account of pale folk in the dark has made half the town think he is mad and the other half avoid the shaft after sunset.",
    "tags": "npc,reputation,world-detail"
  },
  {
    "subject": "Alderman Hobb Greely",
    "fact": "Greely addresses Sera Valen as 'Mistress Valen' and says her arrival is a mercy because they have a situation.",
    "tags": "npc,dialogue,relationship"
  }
]

[
  {
    "subject": "Marla Fenwick",
    "fact": "Marla says the mine fell in and the town began whispering afterward, with fewer songs and more locks on doors.",
    "tags": "npc,world-state,emberhollow"
  },
  {
    "subject": "Alderman Hobb Greely",
    "fact": "Greely has posted a reward and made promises about the collapse, but Marla says he has not paid anything yet.",
    "tags": "npc,promise,reward,collapse"
  },
  {
    "subject": "Tam",
    "fact": "Tam came up from the mine white as tallow and has been talking about pale things in the dark.",
    "tags": "npc,collapse,rumor"
  }
]

[
  {
    "subject": "Alderman Hobb Greely",
    "fact": "Greely is hiding something specific about the mine and was prepared to lie by omission when questioned.",
    "tags": "npc,secrets,lie,collapse"
  },
  {
    "subject": "Alderman Hobb Greely",
    "fact": "When pressed about the mine, Greely's eyes flick toward Tam as if measuring whether Tam will speak.",
    "tags": "npc,relationship,attention,Tam"
  },
  {
    "subject": "Alderman Hobb Greely",
    "fact": "Greely's smile looks forced and out of place, as if borrowed, and he nervously worries a cufflink with his thumb.",
    "tags": "npc,behavior,nervousness"
  },
  {
    "subject": "Marla Fenwick",
    "fact": "Marla openly mocks Greely by saying he sounds rehearsed.",
    "tags": "npc,relationship,conflict,Greely"
  }
